window.ScripturaLexicons.BDAG_PART_0238 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-01\" data-source=\"BDAG\" data-search=\"μνημονεύω verbo lembrar-se; mencionar; conservar na memória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνημονεύω</td><td>verbo</td><td>lembrar-se; mencionar; conservar na memória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-02\" data-source=\"BDAG\" data-search=\"μνημοσύνη, ης, ἡ substantivo feminino memória; recordação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνημοσύνη, ης, ἡ</td><td>substantivo feminino</td><td>memória; recordação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-03\" data-source=\"BDAG\" data-search=\"μνημόσυνον, ου, τό substantivo neutro memória; memorial; oferta memorial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνημόσυνον, ου, τό</td><td>substantivo neutro</td><td>memória; memorial; oferta memorial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-04\" data-source=\"BDAG\" data-search=\"μνησικακέω verbo guardar rancor; nutrir ressentimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνησικακέω</td><td>verbo</td><td>guardar rancor; nutrir ressentimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-05\" data-source=\"BDAG\" data-search=\"μνησικακία, ας, ἡ substantivo feminino rancor; espírito vingativo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνησικακία, ας, ἡ</td><td>substantivo feminino</td><td>rancor; espírito vingativo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-06\" data-source=\"BDAG\" data-search=\"μνησίκακος, ον adjetivo vingativo; rancoroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνησίκακος, ον</td><td>adjetivo</td><td>vingativo; rancoroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-07\" data-source=\"BDAG\" data-search=\"μνηστεύω verbo cortejar; ficar noivo; desposar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνηστεύω</td><td>verbo</td><td>cortejar; ficar noivo; desposar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-08\" data-source=\"BDAG\" data-search=\"μογγιλάλος, ον adjetivo de voz rouca ou cavernosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μογγιλάλος, ον</td><td>adjetivo</td><td>de voz rouca ou cavernosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-09\" data-source=\"BDAG\" data-search=\"μογιλάλος, ον adjetivo com dificuldade de fala; mudo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μογιλάλος, ον</td><td>adjetivo</td><td>com dificuldade de fala; mudo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-10\" data-source=\"BDAG\" data-search=\"μόγις advérbio a custo; com dificuldade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόγις</td><td>advérbio</td><td>a custo; com dificuldade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-11\" data-source=\"BDAG\" data-search=\"μόδιος, ίου, ὁ substantivo masculino medida de cereais; módio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόδιος, ίου, ὁ</td><td>substantivo masculino</td><td>medida de cereais; módio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-12\" data-source=\"BDAG\" data-search=\"μοῖρα, ας, ἡ substantivo feminino sorte; destino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοῖρα, ας, ἡ</td><td>substantivo feminino</td><td>sorte; destino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-13\" data-source=\"BDAG\" data-search=\"μοιχαλίς, ίδος, ἡ substantivo feminino adúltera; infiel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοιχαλίς, ίδος, ἡ</td><td>substantivo feminino</td><td>adúltera; infiel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-14\" data-source=\"BDAG\" data-search=\"μοιχάω verbo cometer adultério; ser infiel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοιχάω</td><td>verbo</td><td>cometer adultério; ser infiel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-15\" data-source=\"BDAG\" data-search=\"μοιχεία, ας, ἡ substantivo feminino adultério; atos de adultério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοιχεία, ας, ἡ</td><td>substantivo feminino</td><td>adultério; atos de adultério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-16\" data-source=\"BDAG\" data-search=\"μοιχεύω verbo cometer adultério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοιχεύω</td><td>verbo</td><td>cometer adultério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-17\" data-source=\"BDAG\" data-search=\"μοιχός, οῦ, ὁ substantivo masculino adúltero; infiel a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μοιχός, οῦ, ὁ</td><td>substantivo masculino</td><td>adúltero; infiel a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-18\" data-source=\"BDAG\" data-search=\"μόλιβος, ου, ὁ substantivo masculino chumbo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόλιβος, ου, ὁ</td><td>substantivo masculino</td><td>chumbo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-19\" data-source=\"BDAG\" data-search=\"μόλις advérbio com dificuldade; raramente; dificilmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μόλις</td><td>advérbio</td><td>com dificuldade; raramente; dificilmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0238-20\" data-source=\"BDAG\" data-search=\"Μόλοχ, ὁ nome próprio masculino Moloque; divindade cananeia-fenícia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μόλοχ, ὁ</td><td>nome próprio masculino</td><td>Moloque; divindade cananeia-fenícia</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0238-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνημονεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνημονεύω</span> (<span class=\"greek\">μνήμων</span>, “aquele que tem em mente”), imperfeito <span class=\"greek\">ἐμνημόνευον</span>; futuro <span class=\"greek\">μνημονεύσω</span> LXX; 1º aoristo <span class=\"greek\">ἐμνημόνευσα</span> (Hdt.+).</p><p class=\"entry-text\">① Lembrar-se, ter em mente, pensar em; também, quando a ênfase recai no aspecto expressivo da recordação, mencionar.</p><p class=\"entry-text\">ⓐ Com genitivo (Pla., Theaet. 191d; Philod., De Piet. 94; Diod S 1, 21, 8; Lucian, Dial. Deor. 4, 7; SIG 284, 8; 620, 25; PSI 502, 2; 651, 2 [III a.C.]; Wsd 2:4; Tob 4:5, 19 BA; Sus 9 Theod.; EpArist 157; PsSol 3:3; 5:16), de pessoa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:7</a>; 21:7; MPol 8:1; IEph 12:2; ISm 5:3; Hm 4, 1, 1. Da menção em oração (Heidelb. Pap.-Sammlung I, ed. Deissmann 1905, n.º 6, 15 <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">οὖν</span>, <span class=\"greek\">δέσποτα</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μνημονεύης</span> <span class=\"greek\">μοι</span> [<span class=\"greek\">μου</span>?] <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁγίας</span> <span class=\"greek\">σου</span> <span class=\"greek\">εὐχάς</span>) IEph 21:1; IMg 14:1.—Com conotação de solicitude (cf. 1 Macc 12:11) <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πτωχῶν</span>, lembrar-se dos pobres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>.—Com genitivo da coisa (Arrian, Peripl. 16, 3 <span class=\"greek\">πόλεως</span> <span class=\"greek\">ἐμνημόνευσεν</span>; ParJer 7:31; ApcEsdr 7:9; Jos., Ant. 2, 162; 6, 93 e outros) <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:20</a>; plural <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a>. <span class=\"greek\">ὧν</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> Pol 2:3. <span class=\"greek\">τῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἐνταλμάτων</span> 2 Cl 17:3. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐντολῶν</span> <span class=\"greek\">αὐτοῦ</span> Hs 1:7. <span class=\"greek\">τῆς</span> <span class=\"greek\">τρυφῆς</span> 6, 5, 4.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:4</a>, 21.—<span class=\"greek\">μ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δεσμῶν</span>, lembrai-vos de minhas prisões <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:18</a>. Talvez aqui se trate de menção ou lembrança em oração, como em <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔργου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, vossa obra de fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a> (MDibelius, Hdb., exc. ad loc.). <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Συρίᾳ</span> <span class=\"greek\">ἐκκλησίας</span> ITr 13:1; IRo 9:1.—<span class=\"greek\">εἰ</span> <span class=\"greek\">ἐκείνης</span> (isto é, <span class=\"greek\">πατρίδος</span>) <span class=\"greek\">ἐμνημόνευον</span>, se pensassem nela, isto é, se tivessem em mente aquela (a pátria terrena) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:15</a>.</p><p class=\"entry-text\">ⓑ Com acusativo (Hdt. 1, 36; X., An. 4, 3, 2, também Herodian 6, 1, 7; BGU 1024 V, 20; Jdth 13:19; 2 Macc 9:21), de pessoa: <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">ἐγηγερμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:8</a>. Passivo, de Policarpo: ele é lembrado especialmente por todos MPol 19:1. Com acusativo de coisa (Philo, Leg. All. 1, 55; Tat. 33, 4) <span class=\"greek\">τοὺς</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">ἄρτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:9</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">κόπον</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">προγεγραμμένα</span> Hv 4, 3, 6. De Deus: <span class=\"greek\">ἐμνημόνευσεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀδικήματα</span> <span class=\"greek\">αὐτῆς</span>, Deus se lembrou dos atos iníquos dela para castigá-los <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:5</a>.</p><p class=\"entry-text\">ⓒ Seguido de <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a>.—Seguido de <span class=\"greek\">ὅτι</span> (Pla., Rep. 480a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:5</a>. Seguido de pergunta indireta (PStras 41, 40 <span class=\"greek\">οὐ</span> <span class=\"greek\">μνημονεύω</span> <span class=\"greek\">δέ</span>, <span class=\"greek\">τί</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μεσειτίᾳ</span> <span class=\"greek\">ἐγένετο</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>; 3:3. Seguido de oração temporal: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:18</a>.</p><p class=\"entry-text\">② Conservar na memória (PsSol 6:11 <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">κυρίου</span>; como no latim memoria tenere aliquid), com acusativo de coisa Hv 1, 3, 3a; 2, 1, 3. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔσχατα</span> <span class=\"greek\">ῥήματα</span> 1, 3, 3b. <span class=\"greek\">ὅσα</span> Papias (2:3, 15).—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 4. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνημοσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνημοσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μνήμων</span>, “aquele que tem em mente”; Hom. e outros), memória: <span class=\"greek\">εἰς</span> <span class=\"greek\">μνημοσύνην</span> <span class=\"greek\">αὐτοῦ</span>, em memória dele GPt 12:54.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνημόσυνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνημόσυνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μνήμων</span>, “aquele que tem em mente”; Hdt. e outros; Kaibel 367, 2; papiros, LXX, En; TestSol 26:8 H; TestJos 7:5; TestJob).</p><p class=\"entry-text\">① Faculdade mental de recordar, memória: <span class=\"greek\">ἔγγραφοι</span> <span class=\"greek\">ἐγένοντο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτοῦ</span>, foram inscritos na memória de Deus 1 Cl 45:8.</p><p class=\"entry-text\">② Estado de conservar algo na lembrança, memória, com genitivo objetivo (frequentemente na LXX) <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινος</span>, em memória de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:9</a> (JJeremias, ZNW 44, ’52/53, 103–7: a “lembrança escatológica” de Deus). <span class=\"greek\">ἐξολεθρεῦσαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span>, extirpar da terra a lembrança deles 1 Cl 22:6; <span class=\"greek\">μήποτε</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. [<span class=\"greek\">ὑμῶν</span>] <span class=\"greek\">ἀπόληται</span>, para que ... não sejais apagados da memória AcPl Ha 1, 22 (Ps 33:17; cf. Sir 10:17; TestJos 7:5).</p><p class=\"entry-text\">③ Oferta que apresenta um adorador diante de Deus, oferta memorial (=<span class=\"hebrew\" dir=\"rtl\">אַזְכָּרָה</span> Lev 2:2, 9, 16; 5:12; cf. Sir 35:6; 38:11; 45:16), figuradamente: <span class=\"greek\">αἱ</span> <span class=\"greek\">προσευχαί</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἀνέβησαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μνημόσυνον</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:4</a> (o acolhimento disso é expresso no versículo 31: <span class=\"greek\">αἷ</span> <span class=\"greek\">ἐλεημοσύναι</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐμνήσθησαν</span>).—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 4. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνησικακέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνησικακέω</span> (<span class=\"greek\">μιμνῄσκω</span>, <span class=\"greek\">κακός</span>), futuro <span class=\"greek\">μνησικακήσω</span>, 1º aoristo <span class=\"greek\">ἐμνησικάκησα</span> (Hdt.+; inscrições, LXX; Test12Patr; Jos., Bell. 4, 94 e outros), recordar uma ofensa com ressentimento, recordar o mal, nutrir rancor, guardar ressentimento <span class=\"greek\">τινί</span>, contra alguém (Thu. 8, 73; Lysias 30, 9; Philo, Virt. 106, De Jos. 17; Jos., Ant. 1, 323) 19:4; Hv 2, 3, 1; Hs 9, 23, 4b. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>: <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐξομολογουμένοις</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">αὐτῶν</span>, guardar rancor contra aqueles que confessaram os próprios pecados ou talvez lançar-lhes em rosto os pecados confessados 9, 23, 4a (cf. Aristoph., Nub. 999 <span class=\"greek\">μ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡλικίαν</span>, “lançar-lhe a idade em rosto”). <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">κακίαν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μνησικακείτω</span>, ninguém dentre vós guarde rancor contra seu próximo 2:8 (Zech 7:10). Absolutamente, com objeto pessoal subentendido: guardar rancor, estar ressentido (Diod S 31, 8, 2; Lucian, Prom. 8) D 2:3; Dg 9:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μνησικακοῦντες</span>, pessoas que guardam rancor Hm 9:3.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 11.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνησικακία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνησικακία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μνησικακέω</span>; Plut., Mor. 860a; Appian, Ital. Fgm. 7; Philo, De Jos. 261; Jos., Ant. 16, 292), ato de guardar rancor, espírito vingativo Hm 8:3 e 10; que causa a morte Hv 2, 3, 1.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 11.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνησίκακος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνησίκακος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">μνησικακέω</span>; Aristot. e outros; Pr 12:28; TestZeb 8:6), vingativo, rancoroso: <span class=\"greek\">μ</span>. <span class=\"greek\">γίνεσθαι</span> Hs 9, 23, 3.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 11.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνηστεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνηστεύω</span>, futuro médio <span class=\"greek\">μνηστεύσομαι</span> LXX; perfeito na 3ª pessoa singular <span class=\"greek\">μεμνήστευται</span> Dt 20:7. Passivo: particípio do 1º aoristo feminino <span class=\"greek\">μνηστευθεῖσα</span>; perfeito <span class=\"greek\">ἐμνηστευμένη</span>, ou <span class=\"greek\">μεμνηστευμένη</span> (B-D-F §68; Mlt-H. 193) (Hom. e outros; Diod S 4, 37, 4; 5; LXX; JosAs 1:9 [<span class=\"greek\">ἐμνηστεύοντο</span> <span class=\"greek\">αὐτήν</span>, “cortejavam-na”]; Jos., C. Ap. 2, 200; a voz média PFlo 36, 4), cortejar e conquistar, desposar, prometer em casamento; na voz passiva, estar prometido em casamento, ficar noivo (Dt 22:25, 27f) <span class=\"greek\">τινί</span>, de alguém (Artem. 2, 12 p. 101, 4 H., variante de leitura; Dt 22:23; Jos., Bell. 1, 508), Maria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:16</a>, variante de leitura (JNolland, CBQ 58, ’96, 665–73), 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:27</a>; 2:5; GJs 19:1.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 1. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μογγιλάλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μογγιλάλος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">μογγός</span>, “de voz rouca e cavernosa”, <span class=\"greek\">λαλέω</span>; Ptolem., Apotel. 3, 13, 3 p. 151, 2 Boll-B.; Georg. Mon. 492, 14 de Boor [1892]; Is 35:6, variante de leitura, Ziegler; ver Thackeray p. 120f.—B-D-F §34, 6; Mlt-H. 106), que fala com voz rouca/cavernosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:32</a>, variante de leitura.—DELG s.v. <span class=\"greek\">μογγός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μογιλάλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μογιλάλος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">μόγις</span>, <span class=\"greek\">λαλέω</span>; sobre a forma, ver B-D-F §34, 6; 119, 5; Rob. 169; 210).</p><p class=\"entry-text\">① Que fala com dificuldade, que tem deficiência da fala (Aëtius 8, 38; escólio a Lucian, p. 68, 5 Rabe; Anecd. Gr. I p. 100, 22; ver JBidez et FCumont, Les mages hellénisés II ’38 p. 334, 8 <span class=\"greek\">μογιλάλοι</span>, com variante de leitura <span class=\"greek\">μογγιλάλοι</span>); esse sentido para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:32</a> é corroborado pelo versículo 35 <span class=\"greek\">ἐλάλει</span> <span class=\"greek\">ὀρθῶς</span> (ver AWeatherhead, ET 23, 1912, 381).</p><p class=\"entry-text\">② Mudo, incapaz de articular (Vett. Val. 73, 12; POxy 465, 228; Is 35:6; —56:10 Aq.; Ex 4:11 Aq., Sym., Theod.); as versões antigas compreendem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:32</a>, 33, variante de leitura, nesse sentido.—DELG s.v. <span class=\"greek\">μόγος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόγις</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόγις</span>, advérbio (Hom. e outros; Diod S; Epict.; Polemo Soph., Decl. 2, 3; 15; Lucian; PMagd 11, 6 [221 a.C.]; POxy 298, 19 [I d.C.]; PLips 105, 10; PSI 49, 2; Wsd 9:16, variante de leitura; 3 Macc 7:6; Philo, In Flacc. 113, variante de leitura; Jos., Ant. 8, 130; 16, 345; Tat. 39, 1.—B-D-F §33; Rob. 296), a custo, com dificuldade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:18</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7</a>, variante de leitura (ver também <span class=\"greek\">μόλις</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a> D.—DELG s.v. <span class=\"greek\">μόγος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόδιος, ίου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόδιος</span>, <span class=\"greek\">ίου</span>, <span class=\"greek\">ὁ</span> (empréstimo latino [modius]: Dinarchus 1, 43 [?]; Dionys. Hal. 12, 1; Epict. 1, 17, 7; 9; Plut., Demetr. 33, 6; inscrições [índice OGI]; PThéad 32, 25; PGen 62, 17; GrBar 6:7; Jos., Ant. 9, 85; 14, 28; 206. Empréstimo também no rabínico), medida de cereais que contém 16 sextários = aproximadamente 8.75 litros, quase um peck, recipiente com capacidade de um peck <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:33</a> (recipiente usado para esconder uma luz, como em Judg 7:16 [<span class=\"greek\">ὑδρίας</span>]; Jos., Ant 5, 223.—Sobre a figura, ADupont-Sommer, Note archéol. sur le prov. évang.: mettre la lampe sous le boisseau = Mél. Syr. à MRDussaud II ’39, 789–94; JJeremias, ZNW 39, ’41, 237–40 Pauly-W. III 1775f; Hultsch, Metrologie2 121ff).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοῖρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοῖρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μείρομαι</span>, “receber sua parte”; Hom. e outros; papiros, TestSol; SibOr 3, 121 e outros; Philo; Jos., Bell. 4, 86, Ant. 17, 303; Just.; Tat. 7:1 [“parte”]), sorte (na vida), destino (PLips 40 II, 26) ApcPt Fgm. 2 p. 12, 19.—LfgrE s.v. (bibliografia). DELG s.v. <span class=\"greek\">μείρομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχαλίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοιχαλίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (=<span class=\"greek\">μοιχάς</span> [Vett. Val. 104, 11], forma feminina mais antiga de <span class=\"greek\">μοιχός</span>; Aëtius [100 d.C.]: Dox. Gr. 301a, 14; Heliod. 8, 9; Procop., Anecd. 1, 36; Syntipas p. 23, 6 e outros [Phryn. 452 Lob.]; Cat. Cod. Astr. VII p. 109, 6; 20; VIII/1 p. 264, 29; VIII/4 p. 146, 26; PCairMasp 97 II, 42; Suda III p. 421, 10; LXX; TestLevi 14:6; ApcSed 6:4 [masculino]; Ar. 11:3; <span class=\"greek\">μοιχοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μοιχαλίδες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ψευδοπροφῆται</span> Hippol., Ref. 9, 15, 3), adúltera.</p><p class=\"entry-text\">ⓐ Literalmente Ro 7:3ab (caso semelhante descrito em Achilles Tat. 8, 10, 11f). <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">μεστοὶ</span> <span class=\"greek\">μοιχαλίδος</span>, olhos cheios (de desejo) por uma adúltera, isto é, sempre à procura de mulher com quem cometer adultério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:14</a> (sobre a expressão, ver <span class=\"greek\">μεστός</span> 2b; cf. Timaeus Hist. [IV a.C.] em <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 4, 5, a respeito de homem moralmente íntegro, <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀφθαλμοῖς</span> <span class=\"greek\">κόρας</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">πόρνας</span> <span class=\"greek\">ἔχων</span> = ter moças, não prostitutas, diante dos olhos; Plut., Mor. 528e).</p><p class=\"entry-text\">ⓑ Em imagem vigorosa que ultrapassa a aparente especificidade do gênero, <span class=\"greek\">μοιχαλίδες</span>, adúlteras (criaturas infiéis, REB e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:4</a>. A variante <span class=\"greek\">μοιχοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μοιχαλίδες</span> sugere que não se levou em conta a reminiscência, pelo autor, do uso encontrado em Oseias (3:1), no qual a relação de Deus com Israel é representada como casamento, e qualquer obscurecimento dessa relação torna-se adultério (cf. Jer 3:9; 9:1; Ezk 16:32ff, especialmente versículo 38; <span class=\"greek\">μοιχαλίς</span> empregado de Adão em ApcSed 6:4; ver W-S. §28, 2b). Como adjetivo, adúltero, infiel: <span class=\"greek\">γενεὰ</span> <span class=\"greek\">μοιχαλίς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:39</a>; 16:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:38</a>.—DELG s.v. <span class=\"greek\">μοιχός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοιχάω</span> (X. e outros: JWackernagel, Hellenistica 1907, 7ff; B-D-F §101 p. 46f), “levar a cometer adultério”; em nossa literatura (assim como na LXX; PsSol 8:10), somente no passivo.</p><p class=\"entry-text\">① Ser levado a cometer adultério, ser adúltero/adúltera, cometer adultério.</p><p class=\"entry-text\">ⓐ De mulher (Ezk 16:32): <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">μοιχᾶσθαι</span>, (o homem que se divorcia de sua esposa) faz com que ela cometa adultério (caso contraia novo casamento) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32a</a>, variante de leitura. <span class=\"greek\">αὐτὴ</span> <span class=\"greek\">μοιχᾶται</span>, ela comete adultério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:12</a>. Mas também</p><p class=\"entry-text\">ⓑ De homem (PsSol 8, 10) que se casa com mulher divorciada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32b</a>; 19:9, variante de leitura, ou que volta a casar depois de divorciar-se de sua esposa 19:9; Hm 4, 1, 6. <span class=\"greek\">μοιχᾶται</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτήν</span>, comete adultério contra ela (a primeira esposa) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:11</a> (NTurner, Bible Translator 7, ’56, 151f: relaciona com Jer 5:9); se compreendida como semitismo (Rehkopf §233, 2 nota 4; ver BSchaller, em Festschr. JJeremias, ’70, 239ff: em aramaico o verbo correspondente com preposição é empregado no sentido de “com”, não “contra”), a expressão pode ser traduzida comete adultério com ela (a segunda esposa).</p><p class=\"entry-text\">ⓒ De homem ou mulher 2 Cl 4:3.</p><p class=\"entry-text\">② Ser culpado de infidelidade numa relação transcendente, ser infiel: <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁμοιώματα</span> <span class=\"greek\">ποιῇ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span>, <span class=\"greek\">μοιχᾶται</span>, quem age como os gentios (isto é, politeístas praticantes do culto de imagens: NBrox, Der Hirt des Hermas ’91, 208) comete adultério (e não se pode esperar que o outro cônjuge mantenha as relações conjugais) Hm 4, 1, 9.—DELG s.v. <span class=\"greek\">μοιχός</span>. M-M. s.v. <span class=\"greek\">μοιχάομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοιχεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μοιχεύω</span>; Andocides e outros; Heraclit. Sto. 69 p. 89, 15; PMich 148 I, 8; LXX; TestSol 1:2 D; GrBar; Philo; Jos., Ant. 16, 340 e outros; apologistas; <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παρθένου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Πανθήρα</span> Orig., C. Cels. I, 32, 6), adultério em sentido literal Hm 4, 1, 5 e 9; ApcPt 9:24. Com outros pecados (Hos 4:2; Theoph. Ant. 2, 34 [p. 186, 9]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:19</a>, variante de leitura; 1 Cl 30:1; 2 Cl 6:4; 20:1; D 5:1; Hm 8:3. Plural (como em D 5:1 acima) que denota atos separados (Pla., Rep. 4, 443a, Leg. 8, 839a; PTebt 276, 16 <span class=\"greek\">πορνεῖαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μοιχεῖαι</span>; GrBar; Philo, Spec. Leg. 2, 13; Jos., Bell. 5, 402; Just., D. 93, 1; Mel., P. 50, 362.—B-D-F §142; W-S. §27, 4d; ver Rob. 408), atos de adultério Mt 15:19=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:22</a> (Did., Gen. 226, 21; Theoph. Ant. 1, 14 [p. 92, 6]; também numa lista de vícios em Plut., Mor. 1050d); cf. D 3:3; AcPl Ha 1, 12. Cf. <span class=\"greek\">καταλαμβάνειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">μοιχείᾳ</span>, apanhar em flagrante adultério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:3</a> (Plut., Mor. 291f; sobre a “mulher adúltera”, ver REisler, ZNW 22, 1923, 305–7; KBornhäuser, NKZ 37, 1926, 353–63; EBishop, JTS 35, ’34, 40–45; JJeremias, ZNW 43, ’51, 148f: narrativa de tentação, cf. Mk 12:13–17; TManson, ZNW 44, ’52/53, 255f; FSchilling, ATR 37, ’55, 91–106; UBecker, Jesus u. die Ehebrecherin ’63; JDerrett, Law in the NT, ’70, 156–87; JMcDonald, NTS 41, ’95, 415–27). Também <span class=\"greek\">εὑρίσκειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. Hm 4, 1, 4.—B. 1456; RAC IV 666–77. DELG s.v. <span class=\"greek\">μοιχός</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοιχεύω</span>, futuro <span class=\"greek\">μοιχεύσω</span>; 1º aoristo <span class=\"greek\">ἐμοίχευσα</span>. Passivo: 1º aoristo passivo na 3ª pessoa singular <span class=\"greek\">ἐμοιχεύθη</span> Sir 23:23; infinitivo <span class=\"greek\">μοιχευθῆναι</span> (Xenophanes, Hecataeus Mil., Aristoph., X. e outros; papiros [ver b<span class=\"greek\">β</span>], LXX; TestSol 1:1f D; TestAbr B; Test12Patr; Philo; Jos., Ant. 16, 296 e outros; Ar.; Just.; Tat., Orig.—HBogner, Was heisst <span class=\"greek\">μ</span>.?: Her 76, ’41, 318–20), cometer adultério.</p><p class=\"entry-text\">ⓐ De ambos os sexos, com referência aos Dez Mandamentos (Ex 20:13; Dt 5:17): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:27</a>; 19:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:9</a>; Js 2:11ab. Uma ou mais dessas passagens podem referir-se apenas ao homem, como abaixo.</p><p class=\"entry-text\">ⓑ Somente do homem.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Absolutamente: Lk 16:18ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:22</a> (<span class=\"greek\">μὴ</span> <span class=\"greek\">μοιχεύειν</span> como em Jos., Ant. 3, 92); 19:4; D 2:2.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Com objeto <span class=\"greek\">τινά</span> (<span class=\"greek\">γυναῖκα</span>), cometer adultério com alguém (Aristoph., Av. 558; Pla., Rep. 2, 360b; Lucian, Dial. Deor. 6, 3; Aristaenet., Ep. 1, 20; PSI 158, 45; TestAbr B 12 p. 116, 14 [Stone p. 80]; Ar. 9, 6; Just., A I, 5, 2; Tat. 34, 2; Hippol., Ref. 5, 23, 13. Cf. Lev 20:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a> (cf. Epict. 2, 18, 15; Sextus 233). Isso explica o uso do passivo no caso de mulher (Chariton 1, 4, 6 <span class=\"greek\">μοιχευομένην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γυναῖκα</span>; Achilles Tat. 6, 9, 7; Sir 23:23; Philo, Decal. 124; Jos., Ant. 7, 131) <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">μοιχευθῆναι</span>, ele faz com que ela cometa adultério (se contrair casamento posterior) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:32</a>; 19:9, variante de leitura. <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">κατείληπται</span> <span class=\"greek\">μοιχευομένη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:4</a> (JMcDonald, NTS 41, ’95, 415–27).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μοιχεύοντες</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:22</a> já se encaminha, pelo menos, para um sentido figurado (cf. Jer 3:9).—RCharles, The Teaching of the NT on Divorce 1921, 91ff; FDölger, Christl. u. hdn, Ächtung des Ehebr. in d. Kultsatzung: Ac III 132–48; GDelling, RAC IV, ’59, 666–80; JFitzmyer, Theological Studies 37, ’76, 197–226 (Mt).—DELG s.v. <span class=\"greek\">μοιχός</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μοιχός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (desde Hipponax [VI a.C.] 67 D.3; Soph.; POxy 1160, 24ff [ver M-M s.v.]; BGU 1024 III, 12; LXX; Test12Patr, Philo, apologistas exceto Mel.; Hippol., Did., Theoph. Ant.).</p><p class=\"entry-text\">① Pessoa infiel ao cônjuge, adúltero; no singular, o referente é masculino, mas em contextos genéricos mulheres podem estar incluídas; literalmente, com <span class=\"greek\">πόρνος</span> (Just., A II, 2, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a>. Com <span class=\"greek\">φθορεύς</span> (cf. Philo, Spec. Leg. 4, 89; Ath. 34:1 [com <span class=\"greek\">παιδερασταί</span>]) 10:7. Com outros pecadores (TestLevi 17:11; Ar. 8, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a>; Hs 6, 5, 5. Paralelo a <span class=\"greek\">κλέπτης</span> 1 Cl 35:8 (Ps 49:18).</p><p class=\"entry-text\">② Pessoa infiel a Deus, adúltero, extensão figurada de 1; com <span class=\"greek\">μοιχαλίς</span> (ver esse verbete b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:4</a>, variante de leitura. Ver <span class=\"greek\">μοιχάω</span>.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλιβος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόλιβος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; PTebt 121, 52; 84; LXX; TestAbr A 20 p. 103, 6f [<span class=\"greek\">μολύβδου</span>; Stone p. 54]; GrBar 5:3 “projétil de chumbo”; Jos., Bell. 6, 278, Ant. 15, 398. Sobre formas e grafias variantes, ver Thackeray 96; 116), chumbo; por seu baixo ponto de fusão, símbolo da terra, destruída no fogo do juízo final 2 Cl 16:3.—DELG s.v. <span class=\"greek\">μόλυβδος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλις</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μόλις</span> (=Hom. <span class=\"greek\">μόγις</span>, de <span class=\"greek\">μόγος</span>, “trabalho árduo”), advérbio “dificilmente, a custo” (trágicos, Thu.+; PTebt 19, 10 [114 a.C.]; PRyl 113, 27; POxy 1117, 19; PGiss 4, 15; LXX; TestAbr A 11 p. 90, 12 [Stone p. 28]; TestJob, EpArist, Philo, Joseph.; Tat. 39, 1, variante de leitura.—B-D-F §33; Rob. 296; ver <span class=\"greek\">μόγις</span>).</p><p class=\"entry-text\">① Relativo ao que é difícil de realizar, com dificuldade (Lycophron, versículo 757; Appian, Liby. 3 §14, Bell. Civ. 1, 8 §33; 1, 77 §351; Ael. Aristid. 48, 43 K.=24 p. 476 D.; Wsd 9:16=<span class=\"greek\">μετὰ</span> <span class=\"greek\">πόνου</span>; Sir 29:6; Philo, Op. M. 80; Jos., Bell. 1, 149) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:39</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:18</a>; 23:29, variante de leitura; 27:7f, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:18</a> (Pr 11:31; cf. Artem. 1, 2 p. 4, 13 <span class=\"greek\">μόλις</span> <span class=\"greek\">ἐσώθη</span>).</p><p class=\"entry-text\">② Relativo à raridade numa escala de ocorrências, não facilmente, só raramente (Nicander, Ther. 281; Synes., Prov. 1, 11 p. 101d: <span class=\"greek\">μόλις</span> [raramente, quase nunca] virtude e boa fortuna se encontram; Sir 21:20; 26:29; 32:7; Jos., C. Ap. 1, 66, Vi. 173) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7</a>; outra possibilidade aqui é</p><p class=\"entry-text\">③ Relativo à raridade numa escala de expectativa, normalmente não (Phlegon: 257 Fgm. 36, 1; 3 Jac.; Achilles Tat. 2, 26, 1), ou dificilmente (Appian, Bell. Civ. 3, 53 §218 <span class=\"greek\">ὀλίγοι</span> <span class=\"greek\">μόλις</span> = muito poucos).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0238-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μόλοχ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μόλοχ</span>, <span class=\"greek\">ὁ</span> (Am 5:26 [Swete] e TestSol 26:2, 4f; ver <span class=\"greek\">Λάμεχ</span> e W-S. §6, 8b; outras edições <span class=\"greek\">Μολόχ</span>—<span class=\"hebrew\" dir=\"rtl\">מֶלֶךְ</span>, com as vogais de <span class=\"hebrew\" dir=\"rtl\">בּשֶׁת</span>), indeclinável; Moloque, deus cananeu-fenício do céu e do sol (Baudissin, RE XIII 269ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:43</a>, numa citação de Am 5:26, em que a LXX traduz as palavras <span class=\"hebrew\" dir=\"rtl\">סִכּוּת</span> <span class=\"hebrew\" dir=\"rtl\">מַלְכְּכֶם</span> por <span class=\"greek\">τὴν</span> <span class=\"greek\">σκηνὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Μολόχ</span> (<span class=\"hebrew\" dir=\"rtl\">סֻכַּת</span> <span class=\"hebrew\" dir=\"rtl\">מֶלֶךְ</span>).—OEissfeldt, Molk als Opferbegriff im Punischen u. Hebr. u. d. Ende des Gottes Moloch ’35 (sobre isso, WvSoden, TLZ 61, ’36, 45f).</p></section></article>"};
